  $('attackLayerControls').hidden=!['layers','auto'].includes(mode);$('settledAttackControl').hidden=mode!=='settlement';
  for(const id of ['attackBase','runtimeStatPercent']){$(id).disabled=mode!=='layers';$(id).required=mode==='layers';}
